```cpp
#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
using namespace std;

string rle(string s) {
    if (s.empty()) return "";
    string wynik = "";
    char prev = s[0];
    int cnt = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s[i] == prev) {
            cnt++;
        } else {
            wynik += prev;
            wynik += to_string(cnt);
            prev = s[i];
            cnt = 1;
        }
    }
    wynik += prev;
    wynik += to_string(cnt);
    return wynik;
}

int main() {
    vector<string> dane = {"aaabbbcccc", "aabbccddee", "abcde", "zzzzzzzzz", "aabbaabb"};

    cout << "a) Kodowanie RLE:" << endl;
    cout << fixed << setprecision(2);
    for (string &s : dane) {
        string zakod = rle(s);
        double kompresja = (double)zakod.length() / s.length();
        cout << "   " << s << " -> " << zakod
             << " (oryg: " << s.length() << ", zakod: " << zakod.length()
             << ", kompresja: " << kompresja << ")" << endl;
    }
    return 0;
}
```

